val credentialManager = CredentialManager.create(context)

suspend fun signIn(activity: Activity): SignInResult {
    val request = GetCredentialRequest(
        listOf(
            GetPublicKeyCredentialOption(requestJson = serverChallengeJson),  // passkey
            GetPasswordOption(),                                              // saved password
        )
    )
    return try {
        val response = credentialManager.getCredential(activity, request)
        when (val cred = response.credential) {
            is PublicKeyCredential -> SignInResult.Passkey(cred.authenticationResponseJson)
            is PasswordCredential  -> SignInResult.Password(cred.id, cred.password)
            else -> SignInResult.Unsupported
        }
    } catch (e: GetCredentialCancellationException) {
        SignInResult.Cancelled
    } catch (e: NoCredentialException) {
        SignInResult.NoneAvailable      // fall back to your sign-up flow
    }
}
